    function FanaticTalentEffect(unit)
        local unit_data = GetUnitData(unit)

            if unit_data.fanatic_speed_bonus then
                ModifyStat(unit, ATTACK_SPEED, unit_data.fanatic_speed_bonus, STRAIGHT_BONUS, false)
            end

            if not IsWeaponTypeTwohanded(unit_data.equip_point[WEAPON_POINT].SUBTYPE) and GetUnitTalentLevel(unit, "talent_fanatic") > 0 then
                unit_data.fanatic_speed_bonus = 7 * GetUnitTalentLevel(unit, "talent_fanatic")
                ModifyStat(unit, ATTACK_SPEED, unit_data.fanatic_speed_bonus, STRAIGHT_BONUS, true)
            else
                unit_data.fanatic_speed_bonus = nil
            end

    end


    function ExaltedArmamentsTalentEffect(unit)
        local unit_data = GetUnitData(unit)

            if unit_data.exalted_bonus then
                ModifyStat(unit, MAGICAL_ATTACK, unit_data.exalted_bonus, MULTIPLY_BONUS, false)
            end

            if IsWeaponTypeTwohanded(unit_data.equip_point[WEAPON_POINT].SUBTYPE) and GetUnitTalentLevel(unit, "talent_exalted_armaments") > 0 then
                unit_data.exalted_bonus = 1.05 + 0.05 * GetUnitTalentLevel(unit, "talent_exalted_armaments")
                ModifyStat(unit, MAGICAL_ATTACK, unit_data.exalted_bonus, MULTIPLY_BONUS, true)
            else
                unit_data.exalted_bonus = nil
            end

    end



    function SummonSpectralWeaponPaladin(caster)
        local unit_data = GetUnitData(caster)
        local power = (1. + GetUnitParameterValue(caster, MINION_POWER) / 100) + GetUnitTalentLevel(caster, "talent_sacred_arsenal") * 0.2
        local variants = {}
        local x, y = GetUnitX(caster), GetUnitY(caster)
        local angle = GetRandomReal(0., 360.)
        local field

            if not unit_data.summoned_arsenal then unit_data.summoned_arsenal = {} end

            if not unit_data.summoned_arsenal.sword then variants[#variants+1] = "u01B" end
            if not unit_data.summoned_arsenal.hammer then variants[#variants+1] = "u01D" end
            if not unit_data.summoned_arsenal.axe then variants[#variants+1] = "u01C" end
            if not unit_data.summoned_arsenal.spear then variants[#variants+1] = "u01E" end


            local dist = GetMaxAvailableDistance(x, y, angle, 400.)
            local summoned = CreateUnit(GetOwningPlayer(caster), FourCC(variants[GetRandomInt(1, #variants)]), x + Rx(dist, angle), y + Ry(dist, angle), GetRandomReal(0., 359.))

            if GetUnitTypeId(summoned) == FourCC("u01B") then unit_data.summoned_arsenal.sword = summoned; field = "sword"
            elseif GetUnitTypeId(summoned) == FourCC("u01D") then unit_data.summoned_arsenal.hammer = summoned; field = "hammer"
            elseif GetUnitTypeId(summoned) == FourCC("u01C") then unit_data.summoned_arsenal.axe = summoned; field = "axe"
            else unit_data.summoned_arsenal.spear = summoned; field = "spear" end

            DelayAction(0., function()
                ModifyStat(summoned, PHYSICAL_ATTACK, (GetUnitParameterValue(caster, PHYSICAL_ATTACK) * 0.4) * power, STRAIGHT_BONUS, true)
                ModifyStat(summoned, MAGICAL_ATTACK, (GetUnitParameterValue(caster, MAGICAL_ATTACK) * 0.4) * power, STRAIGHT_BONUS, true)
            end)

            UnitApplyTimedLife(summoned, 0, 10.)
            DelayAction(10., function()
                KillUnit(summoned)
                unit_data.summoned_arsenal[field] = nil
            end)

    end


    function GrowingFaithTalentEffect(caster)
        local max = 10 + 10 * GetUnitTalentLevel(caster, "talent_growing_faith")


            if GetUnitAbilityLevel(caster, FourCC("A04F")) == 0 then
                ApplyBuff(caster, caster, "A04F", 1)
            else

                if GetBuffLevel(caster, "A04F") < max then
                    SetBuffLevel(caster, "A04F", GetBuffLevel(caster, "A04F") + 1)
                end

                SetBuffExpirationTime(caster, "A04F", -1)
            end

    end


    function ReverseForceTalentEffect(caster)
        local unit_data = GetUnitData(caster)

            unit_data.reverse_force = 0
            unit_data.reverse_timer = CreateTimer()

            TimerStart(unit_data.reverse_timer, 0.5, true, function()
                local attack = GetUnitParameterValue(caster, PHYSICAL_ATTACK)
                local mult = 0.15 + 0.1 * GetUnitTalentLevel(caster, "talent_reverse_force")
                local bonus = math.floor(attack * mult)

                    if unit_data.reverse_force ~= bonus then
                        ModifyStat(caster, MAGICAL_ATTACK, unit_data.reverse_force, STRAIGHT_BONUS, false)
                        ModifyStat(caster, MAGICAL_ATTACK, bonus, STRAIGHT_BONUS, true)
                        unit_data.reverse_force = bonus
                    end

            end)
        
    end


    function AvengingWrathTrigger(unit)
        local level = GetUnitTalentLevel(unit, "talent_avenging_wrath")

            if GetUnitAbilityLevel(unit, FourCC("A04H")) == 0 then
                ApplyBuff(unit, unit, "A04H", 1)
            else
                SetBuffLevel(unit, "A04H", GetBuffLevel(unit, "A04H") + 1)
                SetBuffExpirationTime(unit, "A04H", -1)
            end

            if GetBuffLevel(unit, "A04H") >= 5 then
                RemoveBuff(unit, "A04H")
                ApplyBuff(unit, unit, "A04I", level)
            end

    end


    function LightforgedTrigger(unit, target)
        local range = GetRandomInt(75, 200)
        local angle = AngleBetweenUnits(target, unit) + GetRandomReal(-90., 90.)
        local x,y = GetUnitX(unit) + Rx(range, angle),  GetUnitY(unit) + Ry(range, angle)

            ThrowMissile(unit, target, "lightforged_light_missile", {}, x, y, GetUnitX(target), GetUnitY(target), AngleBetweenUnits(unit, target), false)

    end


    function JudgementalStrikesTalentEffect(source, target)
        local max = GetUnitTalentLevel(source, "talent_judgmental_strikes") * 10
        local level = GetBuffLevel(target, "A04M")
        local min = max - 10
        local current = 1

            if level == 0 then current = min + 1
            else current = min + (10 - max + level) + 1 end

            if current <= max then ApplyBuff(source, target, "A04M", current) end
            SetBuffExpirationTime(target, "A04M", -1.)

    end


    function VengefulTalentEffect(caster)
        local unit_data = GetUnitData(caster)
        local player = GetPlayerId(GetOwningPlayer(caster))+1

        unit_data.vengeful_timer = CreateTimer()
        unit_data.vengeful_bonus = 4
        unit_data.vengeful_current_bonus = 0

        TimerStart(unit_data.vengeful_timer, 0.05, true, function()
            local health = GetUnitState(caster, UNIT_STATE_LIFE) / BlzGetUnitMaxHP(caster)

                if health <= 0.9 then
                    local power = math.floor((1. - health) * 10)
                    local bonus = unit_data.vengeful_bonus * power

                        if bonus ~= unit_data.vengeful_current_bonus then

                            if unit_data.vengeful_current_bonus > 0 then ModifyStat(caster, DAMAGE_BOOST, unit_data.vengeful_current_bonus, STRAIGHT_BONUS, false) end
                            unit_data.vengeful_current_bonus = bonus
                            ModifyStat(caster, DAMAGE_BOOST, unit_data.vengeful_current_bonus, STRAIGHT_BONUS, true)
                            AddStatusBarState("talent_vengeful", "Talents\\BTNDoombringer.blp", POSITIVE_BUFF, player)
                            SetStatusBarValue("talent_vengeful", power, player)
                            SetStatusBarHeaderName("talent_vengeful", LOCALE_LIST[my_locale].TALENTS["talent_vengeful"].name, player)

                        end

                else
                    RemoveStatusBarState("talent_vengeful", player)
                    if unit_data.vengeful_current_bonus > 0 then ModifyStat(caster, DAMAGE_BOOST, unit_data.vengeful_current_bonus, STRAIGHT_BONUS, false) end
                    unit_data.vengeful_current_bonus = 0
                end


        end)

    end

